from lib import *
S = SS('m9')
steps = [
    step("插入 120,000 个文档(每个约 340 字节,k 上有二级索引)并 fsync:dataSize 39,720,000,storageSize 40,747,008,磁盘文件 40,747,008 字节,可复用空闲只有 16,384,索引总大小 2,625,536。", t=tl(S(1)), mark=lidx(S(1), '插入后'), done=lidx(S(1), '文档数'), kv=KV([['dataSize', '39,720,000'], ['磁盘文件', '40,747,008'], ['可复用空闲', '16,384']], ['磁盘文件'])),
    step("deleteMany 删掉 108,000 个文档(0.3 s)后:文档数 12,000,dataSize 降到 3,972,000,但磁盘文件没有变小,反而从 40,747,008 增加到 45,527,040(+4,780,032);“可复用空闲”从 16,384 涨到 40,726,528——空间留在文件里等着复用,没有还给操作系统。", t=tl(S(2)), mark=lidx(S(2), '磁盘文件 40,747,008 → 45,527,040', '删除后'), done=lidx(S(2), 'delete_many'), b=bars([['删除前磁盘文件', 40747008, '40,747,008'], ['删除后磁盘文件', 45527040, '45,527,040'], ['删除后 dataSize', 3972000, '3,972,000'], ['可复用空闲', 40726528, '40,726,528']], 45527040, mark=[1, 3], done=[0, 2]), kv=KV([['dataSize', '39.7 MB → 4.0 MB'], ['磁盘文件', '没有变小(+4.8 MB)'], ['可复用空闲', '16 KB → 40.7 MB']], ['磁盘文件'])),
    step("再插入 100,000 个新文档:磁盘文件 45,527,040 → 45,522,944(-4,096),基本不变;可复用空闲从 40,726,528 降到 6,574,080——新数据先用掉了文件里的空闲空间。", t=tl(S(3)), mark=lidx(S(3), '磁盘文件 45,527,040 → 45,522,944', '再插入'), done=lidx(S(3), '文档数'), kv=KV([['磁盘文件', '45.5 MB → 45.5 MB'], ['可复用空闲', '40.7 MB → 6.6 MB'], ['含义', '删除的空间会被后来的写入复用']], ['含义'])),
    step("再删掉 90,000 个文档后,文件仍是 45,522,944 字节,可复用空闲 36,401,152;执行 compact 返回 bytesFreed 36,347,904(0.2 s),磁盘文件缩小到 9,175,040(减少 36,347,904 字节,80%),可复用空闲只剩 53,248。索引总大小在 compact 前后都是 3,297,280。", t=tl(S(4)), mark=lidx(S(4), 'compact 返回', 'compact 后', '磁盘文件 45,522,944 → 9,175,040'), done=lidx(S(4), '又删除了', '删除后'), b=bars([['compact 前磁盘文件', 45522944, '45,522,944'], ['compact 后磁盘文件', 9175040, '9,175,040']], 45522944, mark=[1], done=[0]), kv=KV([['compact', '把空闲空间还给操作系统'], ['bytesFreed', '36,347,904'], ['索引总大小', '3,297,280,没有变']], ['compact'])),
    step("compact 期间同一个集合上另一个线程不停地 find_one 和 insert_one:compact 本身耗时 0.4 s,期间 6,018 次读和 6,018 次写,读延迟中位数 0.11 ms、最大 5 ms,写延迟中位数 0.10 ms、最大 1 ms,没有任何错误。(这是一个 12,000 文档的小集合上的测量,不代表大集合。)", t=tl(S(5)), mark=lidx(S(5), 'read', 'write'), done=lidx(S(5), 'compact 本身耗时'), kv=KV([['compact 耗时', '0.4 s(小集合)'], ['读写', '照常进行,最大延迟 5 ms'], ['错误', '0']], ['读写'])),
    step("想马上还磁盘:t3 插入 50,000 个文档磁盘文件 16,289,792 字节;deleteMany({}) 后文档数 0,文件仍是 16,293,888,可复用空闲 16,285,696;drop 之后对应的 .wt 文件被删除(exists 为 False)。", t=tl(S(6)), mark=lidx(S(6), 'drop 之后文件还在吗'), done=lidx(S(6), 'deleteMany', 't3 插入'), kv=KV([['deleteMany({})', '文件还在,全是空闲'], ['drop', '文件删除,空间立即还回']], ['drop'])),
]
A = mkartm('m9', 9, 'MongoDB,磁盘空间,compact,delete,WiredTiger,真实验证,动画演示',
    '实测删数据后磁盘为什么不还:删掉 90% 的文档后 dataSize 立刻下降,磁盘文件反而略增,空间变成“可复用空闲”留在文件里;再插入会复用它;compact 把 36 MB 空闲空间还给操作系统(文件 45.5 MB → 9.2 MB);compact 期间读写照常;drop 集合则立即删掉文件。',
    '删了大半数据,磁盘占用为什么没变?这篇用 12 万个文档的集合,对比 deleteMany 前后的 dataSize、storageSize、磁盘文件大小和可复用空闲空间,再看 compact 和 drop 各自能还多少。',
    [('+4.8 MB', 'deleteMany 删掉 90% 的文档后,磁盘文件反而变大的字节数'), ('45.5 → 9.2 MB', 'compact 前后集合磁盘文件的大小,bytesFreed 36,347,904'), ('0 个错误', 'compact 期间另一线程 6,018 次读和 6,018 次写没有失败')],
    [('插入之后', '<p>12 万个文档约 39.7 MB,磁盘文件 40.7 MB,几乎没有可复用空闲。</p>'),
     ('删除不还磁盘', '<p>删掉 90% 后 dataSize 降到约 4 MB,磁盘文件却没变小(反而 +4.8 MB),多出来的 40.7 MB 变成“可复用空闲”留在文件里。</p>'),
     ('空闲会被复用', '<p>再插入 10 万个文档,文件大小几乎不变,可复用空闲降到 6.6 MB:删除的空间留给了后来的写入。</p>'),
     ('compact', '<p><code>compact</code> 把空闲空间还给操作系统:文件从 45.5 MB 降到 9.2 MB。这个实验里索引总大小在 compact 前后没有变化。</p>'),
     ('compact 期间的读写', '<p>在这个 12,000 文档的小集合上,compact 0.4 s,期间同一个集合的读写没有错误,最大延迟 5 ms。大集合上的影响没有测。</p>'),
     ('drop 与 deleteMany', '<p><code>deleteMany({})</code> 之后文件还在,全是空闲空间;<code>drop</code> 才会立刻删文件。</p>')],
    steps,
    [ENV_M + '。每一步都先 fsync 再读 collStats 和 .wt 文件的实际大小;“可复用空闲”是 collStats 里 wiredTiger.block-manager 的 file bytes available for reuse',
     '没有验证:compact 对大集合(GB 级)耗时与对前台读写的影响;compact 是否会重建索引(这里索引总大小没变,原因没有深究);副本集上对 secondary 逐个 compact 的流程;删除时文件为什么增长了 4.8 MB(只观察到现象);TTL 删除与 capped 集合的空间回收;initial sync 或 resync 重建磁盘文件的做法'],
    '删数据与磁盘空间')
